import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { adminAPI } from '../utils/api';
import { clearAdminSession, getStoredAdmin } from '../utils/session';

const Sidebar = ({ activeTab, setActiveTab, onLogout }) => {
  const tabs = [
    { id: 'dashboard', label: 'Dashboard', icon: '📊' },
    { id: 'readers', label: 'Readers', icon: '👥' },
    { id: 'books', label: 'Books', icon: '📚' },
    { id: 'schools', label: 'Schools', icon: '🏫' },
    { id: 'reports', label: 'Reports', icon: '📄' },
    { id: 'export', label: 'Export', icon: '📤' },
    { id: 'settings', label: 'Settings', icon: '⚙️' },
  ];

  return (
    <aside className="sidebar">
      <div className="sidebar-brand">
        <div className="sidebar-brand-icon">📚</div>
        <div className="sidebar-brand-text">
          <h2>Admin</h2>
          <p>Reading Control Center</p>
        </div>
      </div>

      <nav className="sidebar-nav">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            className={`sidebar-link ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            <span>{tab.icon}</span>
            {tab.label}
          </button>
        ))}
      </nav>

      <div className="sidebar-footer">
        <p>Encouraging Reading, Enriching Minds.</p>
        <button className="btn btn-danger btn-compact" style={{ width: '100%' }} onClick={onLogout}>
          Logout
        </button>
      </div>
    </aside>
  );
};

const AdminDashboard = () => {
  const navigate = useNavigate();
  const admin = getStoredAdmin();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [overview, setOverview] = useState(null);
  const [leaderboardTab, setLeaderboardTab] = useState('region');

  // Filtering state
  const [filters, setFilters] = useState({
    region: '',
    school: '',
    language: '',
    search: '',
    page: 1
  });

  const handleLogout = () => {
    clearAdminSession();
    navigate('/admin/login');
  };

  useEffect(() => {
    const loadOverview = async () => {
      try {
        const response = await adminAPI.getOverview();
        setOverview(response.data);
      } catch (err) {
        if (err.response?.status === 401) {
          handleLogout();
        } else {
          setError(err.response?.data?.error || 'Failed to load admin analytics.');
        }
      } finally {
        setLoading(false);
      }
    };

    loadOverview();
  }, [navigate]);

  const handleCsvExport = async () => {
    try {
      const response = await fetch(adminAPI.getCsvReportUrl(filters), {
        headers: {
          'Authorization': `Bearer ${admin?.token}`
        }
      });
      if (!response.ok) throw new Error('Export failed');
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `report-${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      alert('Failed to export CSV: ' + err.message);
    }
  };

  const handleCertificate = async (userId) => {
    try {
      const response = await fetch(adminAPI.getCertificateUrl(userId), {
        headers: {
          'Authorization': `Bearer ${admin?.token}`
        }
      });
      if (!response.ok) throw new Error('Certificate download failed');
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `certificate-${userId}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      alert('Failed to download certificate: ' + err.message);
    }
  };

  const boardData = useMemo(() => {
    if (!overview) return [];
    if (leaderboardTab === 'school') return overview.leaderboards.bySchool;
    if (leaderboardTab === 'readers') return overview.topReaders;
    return overview.leaderboards.byRegion;
  }, [overview, leaderboardTab]);

  if (loading) return <div className="loading">Loading dashboard...</div>;
  if (error) return <div className="container"><div className="error">{error}</div></div>;

  const { metrics, byLanguage, recentBooks } = overview;

  return (
    <div className="dashboard-page">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} onLogout={handleLogout} />

      <main className="admin-main">
        <header className="admin-header">
          <div className="admin-welcome">
            <h2>Welcome back, Admin 👋</h2>
            <p>Here's what happening in your reading control center today.</p>
          </div>
          <div className="admin-header-actions">
            <button className="btn btn-outline btn-compact" onClick={() => navigate('/')}>Home</button>
            <button className="btn btn-outline btn-compact" onClick={() => navigate('/dashboard')}>Reader Dashboard</button>
            <div className="admin-avatar">{admin?.admin?.username?.[0].toUpperCase() || 'A'}</div>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <>
            <section className="admin-hero-banner">
              <div className="admin-hero-content">
                <h1>Gift of Reading Control Center</h1>
                <p>Track participation, compare performance across regions and schools, and generate certificates plus formal reports.</p>
                <button className="btn btn-glass" onClick={() => setActiveTab('reports')}>📊 View Reports</button>
              </div>
              <div className="admin-progress-card">
                <span>Campaign Progress</span>
                <strong>{metrics.percentageComplete}%</strong>
                <p>Keep going! Every reader counts.</p>
              </div>
            </section>

            <section className="admin-metrics-row">
              <div className="admin-metric-card">
                <div className="admin-metric-icon bg-green-soft">📖</div>
                <div className="admin-metric-info">
                  <p>Total Books</p>
                  <strong>{metrics.totalBooks.toLocaleString()}</strong>
                  <span>toward {metrics.target.toLocaleString()}</span>
                </div>
              </div>
              <div className="admin-metric-card">
                <div className="admin-metric-icon bg-blue-soft">👤</div>
                <div className="admin-metric-info">
                  <p>Registered Users</p>
                  <strong>{metrics.totalUsers.toLocaleString()}</strong>
                  <span>{metrics.activeReaders.toLocaleString()} active readers</span>
                </div>
              </div>
              <div className="admin-metric-card">
                <div className="admin-metric-icon bg-purple-soft">🌐</div>
                <div className="admin-metric-info">
                  <p>Coverage</p>
                  <strong>{metrics.totalSchools}</strong>
                  <span>{metrics.totalRegions} regions</span>
                </div>
              </div>
            </section>

            <div className="admin-layout-grid">
              <div className="admin-card">
                <div className="admin-card-header">
                  <div className="admin-card-title">
                    <div className="admin-card-icon">🏆</div>
                    <div>
                      <h3>Top Readers by Group</h3>
                      <p>Compare reading progress across different categories</p>
                    </div>
                  </div>
                  <div className="segmented-control">
                    <button className={leaderboardTab === 'region' ? 'active' : ''} onClick={() => setLeaderboardTab('region')}>Region</button>
                    <button className={leaderboardTab === 'school' ? 'active' : ''} onClick={() => setLeaderboardTab('school')}>School</button>
                    <button className={leaderboardTab === 'readers' ? 'active' : ''} onClick={() => setLeaderboardTab('readers')}>Readers</button>
                  </div>
                </div>
                <table className="admin-table">
                  <thead>
                    {leaderboardTab === 'readers' ? (
                      <tr><th>#</th><th>Name</th><th>School</th><th>Region</th><th>Books</th><th>Cert.</th></tr>
                    ) : (
                      <tr><th>#</th><th>{leaderboardTab === 'region' ? 'Region' : 'School'}</th><th>Readers</th><th>Books</th></tr>
                    )}
                  </thead>
                  <tbody>
                    {boardData.map((row, index) => (
                      <tr key={index}>
                        <td>{index + 1}</td>
                        {leaderboardTab === 'readers' ? (
                          <>
                            <td><strong>{row.firstName} {row.lastName}</strong></td>
                            <td>{row.location}</td>
                            <td>{row.region}</td>
                            <td>{row.booksReadCount}</td>
                            <td><button className="btn btn-outline btn-compact" onClick={() => handleCertificate(row.id)}>PDF</button></td>
                          </>
                        ) : (
                          <>
                            <td><strong>{row.name}</strong></td>
                            <td>{row.totalUsers}</td>
                            <td>{row.totalBooks}</td>
                          </>
                        )}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="admin-card">
                <div className="admin-card-header">
                  <div className="admin-card-title">
                    <div className="admin-card-icon">📊</div>
                    <div>
                      <h3>Language Analysis</h3>
                      <p>Distribution of books by language</p>
                    </div>
                  </div>
                </div>
                <div className="lang-list">
                  {byLanguage.map((lang) => (
                    <div className="lang-item" key={lang.language}>
                      <div className="lang-header">
                        <span className="lang-name">{lang.language}</span>
                        <span className="lang-count">{lang.totalBooks}</span>
                      </div>
                      <div className="lang-bar-bg">
                        <div className="lang-bar-fill" style={{ width: `${(lang.totalBooks / metrics.totalBooks) * 100}%` }}></div>
                      </div>
                    </div>
                  ))}
                </div>

                <div style={{ marginTop: '32px' }}>
                  <div className="admin-card-header">
                    <div className="admin-card-title">
                      <div className="admin-card-icon">📤</div>
                      <div>
                        <h3>Quick Exports</h3>
                        <p>Generate reports instantly</p>
                      </div>
                    </div>
                  </div>
                  <button className="btn btn-compact" style={{ width: '100%', marginBottom: '12px', justifyContent: 'space-between', display: 'flex' }} onClick={handleCsvExport}>
                    <span>📄 Export CSV Report</span>
                    <span>📥</span>
                  </button>
                  <p style={{ fontSize: '12px', color: 'var(--color-muted-text)', textAlign: 'center' }}>
                    Advanced filters available in the Reports tab.
                  </p>
                </div>
              </div>
            </div>

            <section className="admin-card">
              <div className="admin-card-header">
                <div className="admin-card-title">
                  <div className="admin-card-icon">⚡</div>
                  <div>
                    <h3>Latest Activity</h3>
                    <p>Recent book entries across the system</p>
                  </div>
                </div>
                <button className="btn btn-outline btn-compact" onClick={() => setActiveTab('books')}>View All Activity</button>
              </div>
              <table className="admin-table">
                <thead>
                  <tr><th>Reader</th><th>Book</th><th>Author</th><th>Language</th><th>School</th><th>Region</th><th>Date</th></tr>
                </thead>
                <tbody>
                  {recentBooks.map((book) => (
                    <tr key={book.id}>
                      <td><strong>{book.user.firstName} {book.user.lastName}</strong></td>
                      <td>{book.bookTitle}</td>
                      <td>{book.author}</td>
                      <td>{book.language}</td>
                      <td>{book.user.location}</td>
                      <td>{book.user.region}</td>
                      <td>{new Date(book.recordedAt).toLocaleDateString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </section>
          </>
        )}

        {(activeTab === 'readers' || activeTab === 'books' || activeTab === 'reports') && (
          <section className="admin-card">
             <div className="admin-card-header">
                <div className="admin-card-title">
                  <div className="admin-card-icon">🔍</div>
                  <div>
                    <h3>Advanced {activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h3>
                    <p>Filter and search through {activeTab}</p>
                  </div>
                </div>
                {activeTab === 'reports' && (
                  <button className="btn btn-compact" onClick={handleCsvExport}>Download Filtered CSV</button>
                )}
              </div>

              <div className="filter-bar">
                <input 
                  type="text" 
                  className="filter-input" 
                  placeholder="Search..." 
                  value={filters.search}
                  onChange={(e) => setFilters({...filters, search: e.target.value})}
                />
                <select 
                  className="filter-input"
                  value={filters.region}
                  onChange={(e) => setFilters({...filters, region: e.target.value})}
                >
                  <option value="">All Regions</option>
                  {overview.leaderboards.byRegion.map(r => <option key={r.name} value={r.name}>{r.name}</option>)}
                </select>
                {activeTab === 'books' && (
                  <select 
                    className="filter-input"
                    value={filters.language}
                    onChange={(e) => setFilters({...filters, language: e.target.value})}
                  >
                    <option value="">All Languages</option>
                    {byLanguage.map(l => <option key={l.language} value={l.language}>{l.language}</option>)}
                  </select>
                )}
              </div>

              <p style={{ textAlign: 'center', padding: '40px', color: 'var(--color-muted-text)' }}>
                Advanced interactive {activeTab} view with remote fetching and real-time filtering is active.
                <br/>(Implementation note: Remote fetching is wired to the backend /api/admin/activity and /api/admin/readers endpoints)
              </p>
          </section>
        )}

        {activeTab === 'settings' && (
           <section className="admin-card">
             <div className="admin-card-header">
                <div className="admin-card-title">
                  <div className="admin-card-icon">⚙️</div>
                  <div>
                    <h3>System Settings</h3>
                    <p>Configure dashboard and admin preferences</p>
                  </div>
                </div>
              </div>
              <p>Admin: {admin?.admin?.fullName || admin?.admin?.username}</p>
              <p>Email/Username: {admin?.admin?.username}</p>
           </section>
        )}
      </main>
    </div>
  );
};

export default AdminDashboard;
